<script setup>
import {ref,computed,h,nextTick,onMounted,onUnmounted} from 'vue'
import {Circle,SlidersHorizontal,Monitor,Network,HardDrive,Info,Wrench,Cpu,ShieldCheck,Users,FolderKanban,ListChecks,Database,Rocket,Activity,Workflow,Boxes,Blocks,Settings,Sun,Moon,CircleAlert,RefreshCw,WifiOff,LoaderCircle,UserPlus,Power,Trash2,X,KeyRound,Copy,RotateCcw,LockKeyhole,Check} from '@lucide/vue'
const Icons={Circle,SlidersHorizontal,Monitor,Network,HardDrive,Info,Wrench,Cpu,ShieldCheck,Users,FolderKanban,ListChecks,Database,Rocket,Activity,Workflow,Boxes,Blocks,Settings,Sun,Moon,CircleAlert,RefreshCw,WifiOff,LoaderCircle,UserPlus,Power,Trash2,X,KeyRound,Copy,RotateCcw,LockKeyhole,Check}
import {scenes} from './scenes'
const query = new URLSearchParams(location.search)
const scene = scenes.find(s=>s.id===query.get('scene'))||scenes[2]
const page=ref(scene.page), state=ref(scene.state), theme=ref(query.get('theme')==='dark'?'dark':'light'), expanded=ref(false)
const review=ref(query.get('review')==='1'), message=ref(''), busy=ref(false), errors=ref(''), origin=ref(null)
const modal=ref(['create','access','delete','revoke','leave-confirm'].includes(scene.state)?scene.state:'')
const tokenForm=ref(scene.state==='token-form'), tokenResult=ref(scene.state==='token-result'), passwordOpen=ref(scene.state==='password')
const tokenName=ref('工位调用'), ttl=ref('720'), tokenRevoked=ref(false), accountRemoved=ref(false), enabled=ref(true), selected=ref(['delete','password'].includes(scene.state)?'operator':'amvar')
const username=ref(''), displayName=ref(''), password=ref(''), resetPassword=ref(''), revokeSessions=ref(true), revokeTokens=ref(false)
const accessSaved=ref(false), tokenCreated=ref(scene.state==='token-result')
const tokenTarget=ref('default'), defaultRevoked=ref(false)
const tokenRows=computed(()=>[{name:'default',revoked:defaultRevoked.value,expires:'—',used:'2026-11-02 09:08:16'},...(tokenCreated.value?[{name:tokenName.value,revoked:tokenRevoked.value,expires:ttl.value?'2026-12-02 10:20:30':'—',used:'—'}]:[])])
const pagesAllowed=ref(['应用','推理']), operationsAll=ref(scene.state==='access'), projectsAll=ref(true), issueToken=ref(false)
const mode=ref(scene.state==='projects'?'projects':'app'), project=ref('default'), runtime=ref(scene.state==='invalid'?'missing':'display'), dirty=ref(scene.state==='leave-confirm'), pendingPage=ref('services')
const allPages=['项目','任务','数据集','模型','部署','推理','图编辑','应用','应用模式','集成','节点','设置']
const allOperations=['查看项目','编辑项目','查看数据集','导入数据集','管理模型','执行训练','管理部署','执行推理','编辑工作流','运行工作流','管理触发源','查看系统','管理用户']
const selectedProjects=ref(['默认项目'])
const operations=ref(['查看项目','执行推理','运行工作流']), readonly=computed(()=>state.value==='readonly')
const nav=[['preferences','偏好','SlidersHorizontal'],['startup','启动页面','Monitor'],['services','运行状态','Network'],['group','系统环境','HardDrive'],['about','关于','Info'],['host','系统信息','HardDrive'],['python','Python 运行时','Wrench'],['devices','设备信息','Cpu'],['group','访问控制','ShieldCheck'],['session','会话与权限','ShieldCheck'],['accounts','用户管理','Users']]
const mainNav=[['项目','FolderKanban'],['任务','ListChecks'],['数据集','Database'],['模型','Cpu'],['部署','Rocket'],['推理','Activity'],['图编辑','Workflow'],['应用','Boxes'],['集成','Network'],['节点','Blocks'],['设置','Settings']]
const Icon=(props)=>h(Icons[props.name]||Icons.Circle,{size:props.size||18,strokeWidth:1.7,'aria-hidden':true})
const Badge=(props)=>h('span',{class:['badge',props.tone||'neutral']},[props.tone==='good'||props.tone==='bad'||props.tone==='warn'?h('i'):null,props.text])
const fields=(list)=>list.map(([label,value])=>({label,value}))
const expandedConsumers=ref(scene.state==='details'?[2]:[])
const workerLabels=['数据集导入','数据集导出','模型训练','模型转换','模型评估','模型推理']
const workerNames=['dataset import','dataset export','training','conversion','evaluation','inference']
const consumers=['dataset-import','resource-cleanup, model-deployment-transfer, dataset-export','yolox-training, yolov8-training, yolo11-training, yolo26-training, rfdetr-training, classification-training, segmentation-training, pose-training, obb-training','yolox-conversion, yolov8-conversion, yolo11-conversion, yolo26-conversion, rfdetr-conversion','detection-evaluation, classification-evaluation, segmentation-evaluation, pose-evaluation, obb-evaluation','detection-inference, classification-inference, segmentation-inference, pose-inference, obb-inference']
const workerIds=['dataset-import','dataset-export','training','conversion','evaluation','inference']
const pids=['42688','36960','23236','15960','23388','38552']
const dependencies=[['fastapi','0.136.3','fastapi'],['pydantic','2.13.4','pydantic'],['sqlalchemy','2.0.50','sqlalchemy'],['opencv-python','4.13.0.92','cv2'],['numpy','2.4.4','numpy'],['torch','2.12.1+cu126','torch'],['onnxruntime','1.26.0','onnxruntime'],['openvino','2026.2.0','openvino'],['tensorrt','—','tensorrt'],['pyzmq','27.1.0','zmq']]
const hostFields=fields([['OS','Windows-11-10.0.26200-SP0'],['CPU','Intel64 Family 6 Model 141 Stepping 1, GenuineIntel / 16'],['内存（可用 / 总量）','15.9 GiB / 39.6 GiB'],['工作目录','W:\\workspace\\codex\\python\\amvision'],['数据目录','W:\\workspace\\codex\\python\\amvision\\data'],['对象存储根目录','W:\\workspace\\codex\\python\\amvision\\data\\files'],['队列目录','W:\\workspace\\codex\\python\\amvision\\data\\queue'],['自定义节点目录','W:\\workspace\\codex\\python\\amvision\\custom_nodes']])
const pythonFields=fields([['Python 版本','3.12.13 | packaged by Anaconda, Inc. | [MSC v.1942 64 bit (AMD64)]'],['Python 路径','D:\\software\\anaconda3\\envs\\amvision\\python.exe'],['Conda 环境','amvision'],['Conda 目录','D:\\software\\anaconda3\\envs\\amvision'],['虚拟环境','—'],['同目录 Python','否']])
const modalTitle=computed(()=>({create:'创建用户',access:'编辑权限',delete:'删除用户',revoke:'撤销 Token','leave-confirm':'离开启动设置？'}[modal.value]||''))
const canSubmit=computed(()=>!busy.value&&(modal.value!=='create'||(username.value.trim()&&password.value.length>=8&&pagesAllowed.value.length&&(projectsAll.value||selectedProjects.value.length))))
const startupValid=computed(()=>mode.value==='projects'||(['display','stopped'].includes(runtime.value)&&project.value==='default'))
let toastTimer,jobTimer
function notify(text){message.value=text;clearTimeout(toastTimer);toastTimer=setTimeout(()=>message.value='',3500)}
function setOperation(value,checked){operations.value=checked?[...new Set([...operations.value,value])]:operations.value.filter(v=>v!==value)}
function navigate(id){if(page.value==='startup'&&dirty.value&&id!=='startup'){pendingPage.value=id;openModal('leave-confirm');return}page.value=id;state.value='normal';errors.value='';nextTick(()=>document.querySelector('main').scrollTo(0,0))}
function openModal(name){origin.value=document.activeElement;errors.value='';modal.value=name;nextTick(()=>document.querySelector('dialog input:not([disabled]), dialog button')?.focus())}
function closeModal(){if(busy.value)return;modal.value='';errors.value='';nextTick(()=>origin.value?.focus?.())}
function changeStartup(){dirty.value=true;errors.value=''}
function saveStartup(){if(!startupValid.value){errors.value='请选择可用的运行实例。';return}busy.value=true;jobTimer=setTimeout(()=>{busy.value=false;dirty.value=false;notify('启动页面已保存')},250)}
function restore(){mode.value='projects';runtime.value='display';project.value='default';dirty.value=false;state.value='normal';notify('已恢复默认启动页面')}
function refresh(){busy.value=true;jobTimer=setTimeout(()=>{busy.value=false;if(state.value!=='readonly')state.value='normal';notify('状态已更新')},300)}
function submit(){if(!canSubmit.value)return;busy.value=true;jobTimer=setTimeout(()=>{busy.value=false;const action=modal.value;closeModal();if(action==='create'){selected.value=username.value;accessSaved.value=true;if(issueToken.value){tokenCreated.value=true;tokenResult.value=true}notify('用户已创建')}if(action==='access'){accessSaved.value=true;notify('权限已保存')};if(action==='delete'){accountRemoved.value=true;selected.value='amvar';notify('用户已删除')}if(action==='revoke'){if(tokenTarget.value==='default')defaultRevoked.value=true;else{tokenRevoked.value=true;tokenResult.value=false};notify('Token 已撤销')}if(action==='leave-confirm'){dirty.value=false;page.value=pendingPage.value;state.value='normal'}},250)}
function createToken(){if(!tokenName.value.trim()){errors.value='请输入 Token 名称。';return}if(ttl.value!==''&&(!Number.isInteger(Number(ttl.value))||Number(ttl.value)<1)){errors.value='有效期必须为正整数小时。';return}errors.value='';tokenForm.value=false;tokenCreated.value=true;tokenResult.value=true;notify('Token 已创建')}
async function copy(){try{await navigator.clipboard.writeText('DEMO-ONLY-NOT-A-VALID-TOKEN');notify('已复制示例 Token')}catch{errors.value='复制失败，请选中文本后复制。'}}
function reset(){if(resetPassword.value.length<8){errors.value='密码至少为8位。';return}resetPassword.value='';errors.value='';notify('密码已重置')}
function keydown(e){if(!modal.value)return;if(e.key==='Escape'){e.preventDefault();closeModal()}if(e.key==='Tab'){const nodes=[...document.querySelectorAll('dialog button:not([disabled]),dialog input:not([disabled]),dialog select:not([disabled]),dialog summary')];const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}}
function setTheme(v){theme.value=v;document.documentElement.dataset.theme=v}
function changeScene(e){location.href='/?review=1&scene='+e.target.value+'&theme='+theme.value}
onMounted(()=>{setTheme(theme.value);document.addEventListener('keydown',keydown);if(modal.value)nextTick(()=>document.querySelector('dialog input,dialog button')?.focus())})
onUnmounted(()=>{clearTimeout(jobTimer);clearTimeout(toastTimer);document.removeEventListener('keydown',keydown)})
</script>

<template>
<div class="workspace" :class="{expanded}">
  <aside class="global-nav" :inert="!!modal">
    <button class="logo" :aria-label="expanded?'收起导航栏':'展开导航栏'" @click="expanded=!expanded"><img src="/logo.svg" alt="AM"><span v-if="expanded">AMVAR Vision</span></button>
    <nav><button v-for="([label,icon]) in mainNav" :key="label" :aria-label="label" :title="label" :class="{active:label==='设置'}" @click="label==='设置'?navigate('services'):notify('本样稿仅演示设置分类')"><Icon :name="icon"/><span v-if="expanded">{{label}}</span></button></nav>
    <button class="avatar" aria-label="设计预览工具" @click="review=!review">am</button>
  </aside>
  <aside class="settings-nav" :inert="!!modal"><template v-for="([id,label,icon],index) in nav" :key="label"><div v-if="id==='group'" class="nav-group"><Icon :name="icon" :size="16"/>{{label}}</div><button v-else :class="{active:page===id,nested:index>3}" @click="navigate(id)"><Icon :name="icon" :size="17"/>{{label}}</button></template></aside>
  <main :inert="!!modal" :data-page="page">
    <section v-if="page==='preferences'" class="panel"><h2>界面偏好</h2><div class="form-row"><strong>语言</strong><select aria-label="语言"><option>中文</option><option>English</option></select></div><div class="form-row"><strong>主题</strong><div class="segments"><button :class="{active:theme==='light'}" @click="setTheme('light')"><Icon name="Sun"/>亮色</button><button :class="{active:theme==='dark'}" @click="setTheme('dark')"><Icon name="Moon"/>暗色</button></div></div></section>
    <section v-if="page==='startup'" class="panel"><h2>启动页面</h2><div class="form-row"><strong>打开方式</strong><div class="segments"><button :class="{active:mode==='projects'}" @click="mode='projects';changeStartup()">项目页面</button><button :class="{active:mode==='app'}" @click="mode='app';changeStartup()">应用模式</button></div></div><template v-if="mode==='app'"><div class="form-row"><strong>项目</strong><select v-model="project" @change="runtime=project==='empty'?'':'display';changeStartup()" aria-label="项目"><option value="default">默认项目</option><option value="empty">连接器检测项目</option></select></div><div class="form-row"><strong>运行实例</strong><div><div class="inline"><select v-model="runtime" :disabled="project==='empty'" @change="changeStartup" aria-label="运行实例"><option v-if="project==='empty'" value="">暂无运行实例</option><option value="display">摆盘分拣3570显示结果 · 显示结果 runtime</option><option value="stopped">连接器尺寸测量 · 已停止</option><option v-if="state==='invalid'" value="missing">原运行实例已不存在</option></select><Badge v-if="runtime==='display'" tone="good" text="运行中"/><Badge v-if="runtime==='stopped'" text="已停止"/></div><small v-if="runtime==='stopped'">打开页面不会自动启动运行实例。</small><small v-if="project==='empty'">项目中没有可选择的运行实例。</small></div></div></template><div v-if="state==='invalid'&&runtime==='missing'" class="alert bad"><Icon name="CircleAlert"/>原运行实例已删除，请重新选择。</div><p v-if="errors" class="error" role="alert">{{errors}}</p><footer><button @click="restore">恢复默认</button><button class="primary" :disabled="!dirty||!startupValid||busy" @click="saveStartup">{{busy?'保存中…':'保存'}}</button></footer></section>
    <section v-if="page==='services'" class="panel"><header><h2>服务信息</h2><div class="inline"><small>{{state==='loading'?'尚未获取':(state==='stale'?'上次检查':'检查于')+' 10:20:30'}}</small><button :disabled="busy||state==='loading'" @click="refresh"><Icon name="RefreshCw" :size="16"/>刷新</button></div></header><div v-if="state==='stale'" class="alert warn"><Icon name="WifiOff"/>连接中断，当前显示上次检查结果。<button @click="refresh">重新检查</button></div><div v-if="state==='loading'" class="alert neutral"><Icon name="LoaderCircle"/>正在获取服务状态…</div>
      <div class="services"><div v-for="([name,text],i) in [['backend-service','正常'],['backend-worker','运行中'],['WebSocket','已配置'],['ZeroMQ','可用'],['Database','可访问'],['LocalBufferBroker','正常']]" :key="name"><strong>{{name}}</strong><Badge :tone="state==='loading'?'neutral':state==='partial'&&i===1?'warn':i===2?'neutral':'good'" :text="state==='loading'?'未获取':state==='partial'&&i===1?'部分异常':text"/></div></div>
      <div class="worker"><header><div class="worker-heading"><h3>Backend Worker</h3><span class="muted">{{state==='loading'?'—':state==='partial'?'5 / 6':'6 / 6'}} Profile</span></div><Badge :tone="state==='loading'?'neutral':state==='partial'?'warn':'good'" :text="state==='loading'?'未获取':state==='partial'?'部分异常':'运行中'"/></header>

        <div class="table-scroll"><table class="workers"><colgroup><col style="width:19%"><col style="width:14%"><col style="width:16%"><col style="width:10%"><col style="width:13%"><col style="width:14%"><col style="width:14%"></colgroup><thead><tr><th v-for="title in ['Profile','状态','消费者','并发数','进程 ID','心跳时间','原因']">{{title}}</th></tr></thead><tbody><tr v-if="state==='loading'"><td colspan="7" class="empty">正在读取 Worker 状态</td></tr><template v-for="(name,i) in state==='loading'?[]:workerNames" :key="name"><tr><td><span class="profile-name" :title="'amvision '+name+' worker'">{{workerLabels[i]}}</span><small>{{workerIds[i]}}</small></td><td><Badge :tone="state==='partial'&&i===3?'bad':'good'" :text="state==='partial'&&i===3?'未响应':'运行中'"/></td><td class="consumers"><button class="consumer-toggle" :aria-label="workerLabels[i]+'消费者'" :aria-expanded="expandedConsumers.includes(i)" @click="expandedConsumers=expandedConsumers.includes(i)?expandedConsumers.filter(v=>v!==i):[...expandedConsumers,i]"><span aria-hidden="true">{{expandedConsumers.includes(i)?'▾':'▸'}}</span>{{consumers[i].split(', ').length}} 项</button></td><td class="nowrap">1</td><td class="nowrap">{{pids[i]}}</td><td class="nowrap">{{state==='partial'&&i===3?'32 秒前':`${i%2?'0.5':'1.1'} 秒前`}}</td><td>{{state==='partial'&&i===3?'心跳超时':'—'}}</td></tr><tr v-if="expandedConsumers.includes(i)" class="consumer-row"><td colspan="7"><div class="consumer-details"><strong>{{workerLabels[i]}} · 消费者</strong><div class="consumer-grid"><span v-for="consumer in consumers[i].split(', ')" :key="consumer">{{consumer}}</span></div></div></td></tr></template></tbody></table></div>
      <details class="technical" :open="state==='details'"><summary>技术信息</summary><dl class="metadata"><div v-for="f in fields([['Topology id','amvision-backend-workers'],['Generation','37'],['Epoch','epoch-41047a4daac74e7292fcb860c76fe540'],['激活时间','2026-10-29 20:55:53']])" :key="f.label"><dt>{{f.label}}</dt><dd>{{state==='loading'?'—':f.value}}</dd></div></dl></details>
      </div><dl class="metadata lower"><div v-for="f in fields([['API 地址','http://127.0.0.1:5600/api/v1'],['WS 地址','ws://127.0.0.1:5600/ws/v1'],['运行模式','local'],['Backend 状态',state==='loading'?'—':'ok']])"><dt>{{f.label}}</dt><dd>{{f.value}}</dd></div></dl><details><summary>平台能力</summary><dl class="metadata"><div><dt>任务</dt><dd>训练、转换、评估、推理</dd></div><div><dt>协议</dt><dd>REST API、WebSocket、ZeroMQ</dd></div></dl></details></section>
    <section v-if="page==='about'" class="panel"><header><h2>关于</h2></header><dl class="metadata roomy"><div v-for="f in fields([['应用名称','amvar vision'],['版本类型','Community Edition'],['前端版本','0.1.8'],['后端版本','0.1.8'],['Git commit','74f4f559'],['构建时间','—'],['运行模式','local'],['许可证','PolyForm Noncommercial License 1.0.0'],['amvar','amvar.io'],['GitHub 仓库','github.com/ammm56/amvision']])"><dt>{{f.label}}</dt><dd><a v-if="f.label==='amvar'||f.label==='GitHub 仓库'" :href="'https://'+f.value" target="_blank" rel="noopener">{{f.value}}</a><template v-else>{{f.value}}</template></dd></div></dl></section>
    <section v-if="page==='host'" class="panel"><h2>系统信息</h2><dl class="metadata roomy"><div v-for="f in hostFields"><dt>{{f.label}}</dt><dd>{{f.value}}</dd></div></dl><div class="table-scroll"><table><thead><tr><th>磁盘</th><th>路径</th><th>可用空间</th><th>总空间</th></tr></thead><tbody><tr v-for="(label,i) in ['工作目录','数据目录','对象存储']"><td>{{label}}</td><td>W:\workspace\codex\python\amvision{{i?'\\data':''}}{{i===2?'\\files':''}}</td><td class="nowrap">600.8 GiB</td><td class="nowrap">1024.0 GiB</td></tr></tbody></table></div></section>
    <section v-if="page==='python'" class="panel"><h2>Python 运行时</h2><dl class="metadata roomy"><div v-for="f in pythonFields"><dt>{{f.label}}</dt><dd>{{f.value}}</dd></div></dl><div v-if="state==='error'" class="alert bad"><Icon name="CircleAlert"/>当前 NVIDIA profile 有2项依赖异常。<button @click="refresh">重新检查</button></div><div class="table-scroll"><table><thead><tr><th>依赖</th><th>状态</th><th>版本</th><th>导入名称</th></tr></thead><tbody><tr v-for="([name,version,importName],i) in dependencies"><td>{{name}}</td><td><Badge :tone="state==='error'&&(i===5||i===8)?'bad':'neutral'" :text="state==='error'&&i===5?'导入失败':state==='error'&&i===8?'未安装':'已安装'"/></td><td>{{state==='error'&&i===8?'—':version}}</td><td>{{importName}}</td></tr></tbody></table></div><details v-if="state==='error'"><summary>查看错误详情</summary><p>torch：动态库加载失败。检查运行时依赖后重新检测。</p><p>tensorrt：当前环境未找到安装包。</p></details></section>
    <section v-if="page==='devices'" class="panel"><h2>设备信息</h2><div class="device-status"><div v-for="([name,text,tone]) in state==='cpu'?[['CUDA','未配置','neutral'],['OpenVINO','可用','good'],['TensorRT','未配置','neutral'],['ONNX Runtime','已安装','neutral'],['NPU 运行时','未配置','neutral']]:[['CUDA','可用','good'],['OpenVINO','已安装','neutral'],['TensorRT','已安装','neutral'],['ONNX Runtime','已安装','neutral'],['NPU 运行时','未配置','neutral']]"><strong>{{name}}</strong><Badge :tone="tone" :text="text"/></div></div><div v-if="state==='cpu'" class="alert neutral"><Icon name="Cpu"/>当前使用 CPU 推理。</div><div class="table-scroll"><table><thead><tr><th>设备</th><th>驱动</th><th>{{state==='cpu'?'类型':'显存'}}</th></tr></thead><tbody><tr><td>{{state==='cpu'?'Intel CPU':'NVIDIA GeForce RTX 3060 Laptop GPU'}}</td><td>{{state==='cpu'?'—':'595.79'}}</td><td>{{state==='cpu'?'CPU':'6144 MiB'}}</td></tr></tbody></table></div></section>
    <template v-if="page==='session'"><section class="panel"><h2>会话与权限</h2><dl class="metadata roomy"><div v-for="f in fields([['当前用户','amvar'],['登录状态','已自动登录'],['认证方式','本地'],['操作权限','所有权限'],['项目范围','全部项目']])"><dt>{{f.label}}</dt><dd>{{f.value}}</dd></div></dl><details><summary>凭据类型</summary><dl class="metadata"><div><dt>当前凭据</dt><dd>浏览器会话</dd></div><div><dt>账号来源</dt><dd>本地账号</dd></div></dl></details></section><section class="panel"><h2>可访问项目</h2><table><thead><tr><th>项目</th><th>项目ID</th><th>项目来源</th><th>当前</th></tr></thead><tbody><tr><td>默认项目</td><td>project-1</td><td>本地磁盘</td><td>是</td></tr></tbody></table></section><section class="panel"><h2>账号来源</h2><table><thead><tr><th>账号来源</th><th>类型</th><th>认证方式</th><th>能力</th><th>启用</th></tr></thead><tbody><tr><td>本地账号</td><td>local</td><td>密码</td><td>密码登录、刷新 Token、初始化管理员、用户管理、长期 Token</td><td>已启用</td></tr></tbody></table></section></template>
    <section v-if="page==='accounts'" class="panel"><header><h2>用户管理</h2><div class="inline"><button @click="refresh" :disabled="busy"><Icon name="RefreshCw" :size="16"/>刷新</button><button class="primary" :disabled="readonly" @click="openModal('create')"><Icon name="UserPlus" :size="16"/>创建用户</button></div></header><div v-if="readonly" class="alert neutral"><Icon name="LockKeyhole"/>当前账号只有查看权限。</div><div class="accounts-layout"><aside class="user-list"><button :class="{active:selected==='amvar'}" @click="selected='amvar'"><strong>amvar</strong><small>amvar</small><Badge tone="good" text="已启用"/></button><button v-if="selected!=='amvar'&&!accountRemoved" class="active"><strong>现场操作员</strong><small>{{selected}}</small><Badge tone="good" text="已启用"/></button></aside><div class="account-detail"><header><div><h3>{{selected==='amvar'?'amvar':'现场操作员'}}</h3><small class="id">{{selected==='amvar'?'user-ebc12d29f6996bf4ded1a4b278136e9a':'user-88ad42a3056245f58be89d794bf47556'}}</small></div><div class="inline account-actions"><button :disabled="readonly" @click="openModal('access')">编辑权限</button><button :disabled="readonly||selected==='amvar'" :title="selected==='amvar'?'唯一的 amvar 用户不能禁用或删除':''" @click="enabled=!enabled;notify(enabled?'用户已启用':'用户已禁用')"><Icon name="Power" :size="15"/>{{enabled?'禁用':'启用'}}</button><button class="danger" :disabled="readonly||selected==='amvar'" :title="selected==='amvar'?'受保护的用户不能删除':''" @click="openModal('delete')"><Icon name="Trash2" :size="15"/>删除</button></div></header><dl class="metadata roomy"><div><dt>页面权限</dt><dd>按操作权限显示页面</dd></div><div><dt>状态</dt><dd><Badge :tone="enabled?'good':'neutral'" :text="enabled?'已启用':'已禁用'"/></dd></div><div><dt>操作权限</dt><dd>{{!accessSaved||operationsAll?'所有权限':operations.join('、')||'未选择'}}</dd></div><div><dt>项目范围</dt><dd>{{!accessSaved||projectsAll?'全部项目':'指定项目'}}</dd></div><div><dt>最近登录</dt><dd>2026-10-08 17:24:14</dd></div></dl>
      <div v-if="tokenResult" class="token-result"><header><strong>Token 已创建</strong><button aria-label="关闭Token显示" @click="tokenResult=false"><Icon name="X" :size="16"/></button></header><p>仅本次显示，请复制后妥善保存。</p><div class="inline"><input readonly value="DEMO-ONLY-NOT-A-VALID-TOKEN" aria-label="Token 示例"><button @click="copy"><Icon name="Copy" :size="16"/>复制</button></div></div>
      <header class="section-heading"><h3>长期 Token 管理</h3><button :disabled="readonly" @click="tokenForm=!tokenForm"><Icon name="KeyRound" :size="16"/>{{tokenForm?'收起创建':'创建 Token'}}</button></header><div v-if="tokenForm" class="token-form"><label>Token 名称<input v-model="tokenName"></label><label>有效期（小时）<input v-model="ttl" type="number" min="1" step="1" placeholder="留空永久有效"></label><button class="primary" @click="createToken">创建</button></div><p v-if="errors&&!modal" class="error" role="alert">{{errors}}</p><div class="table-scroll"><table class="token-table"><thead><tr><th>Token</th><th>状态</th><th>过期时间</th><th>最近使用</th><th>操作</th></tr></thead><tbody><tr v-for="t in tokenRows" :key="t.name"><td>{{t.name}}</td><td><Badge :tone="t.revoked?'neutral':'good'" :text="t.revoked?'已撤销':'有效'"/></td><td>{{t.expires}}</td><td>{{t.used}}</td><td><button class="danger" :disabled="readonly||t.revoked" @click="tokenTarget=t.name;openModal('revoke')">撤销</button></td></tr></tbody></table></div>
      <details :open="passwordOpen"><summary @click.prevent="passwordOpen=!passwordOpen">用户密码重置</summary><label>新密码<input v-model="resetPassword" type="password" autocomplete="new-password" :disabled="readonly"></label><div class="inline checks"><label><input type="checkbox" v-model="revokeSessions" :disabled="readonly">撤销现有会话</label><label><input type="checkbox" v-model="revokeTokens" :disabled="readonly">撤销长期 Token</label></div><button :disabled="readonly||!resetPassword" @click="reset"><Icon name="RotateCcw" :size="16"/>重置密码</button></details>
    </div></div></section>
  </main>
</div>
<div v-if="message" class="toast" role="status"><Icon name="Check"/>{{message}}</div>
<div v-if="modal" class="overlay" @click.self="closeModal"><dialog open aria-modal="true" :aria-label="modalTitle" :class="{wide:modal==='create'||modal==='access'}"><header><h2>{{modalTitle}}</h2><button aria-label="关闭" @click="closeModal" :disabled="busy"><Icon name="X"/></button></header><div class="dialog-body">
  <template v-if="modal==='create'"><div class="two-columns"><label>用户名<input v-model.trim="username" autocomplete="off" placeholder="例如 operator" required></label><label>显示名称<input v-model="displayName" placeholder="例如 现场操作员"></label></div><label>密码<input v-model="password" type="password" autocomplete="new-password" placeholder="至少8位" required @input="errors=''" @blur="password&&password.length<8&&(errors='密码至少为8位。')"></label></template>
  <template v-if="modal==='create'||modal==='access'"><p v-if="modal==='access'" class="muted">{{selected==='amvar'?'amvar':'现场操作员'}}</p><fieldset><legend>页面权限 <small>{{pagesAllowed.length}} / {{allPages.length}}</small></legend><div class="check-grid"><label v-for="p in allPages"><input type="checkbox" :value="p" v-model="pagesAllowed">{{p}}</label></div></fieldset><fieldset><legend>操作权限 <small>{{operationsAll?allOperations.length:operations.length}} / {{allOperations.length}}</small></legend><label class="checks"><input type="checkbox" v-model="operationsAll">全部操作</label><div class="check-grid" :class="{muted:operationsAll}"><label v-for="op in allOperations"><input type="checkbox" :value="op" :checked="operationsAll||operations.includes(op)" @change="setOperation(op,$event.target.checked)" :disabled="operationsAll">{{op}}</label></div></fieldset><fieldset><legend>项目范围</legend><div class="inline checks"><label><input type="radio" name="project-scope" :value="true" v-model="projectsAll">全部项目</label><label><input type="radio" name="project-scope" :value="false" v-model="projectsAll">指定项目</label></div><div v-if="!projectsAll" class="check-grid project-choices"><label v-for="p in ['默认项目','连接器检测项目']"><input type="checkbox" v-model="selectedProjects" :value="p">{{p}}</label></div></fieldset><template v-if="modal==='create'"><label class="checks"><input type="checkbox" v-model="issueToken">同时创建长期 Token</label><label v-if="issueToken">Token 名称<input v-model="tokenName"></label></template></template>
  <template v-if="modal==='delete'"><div class="confirm-title"><Icon name="Trash2"/>现场操作员</div><p>删除后该用户将无法登录，已有会话与 Token 将失效。</p><p class="muted">项目、数据集和模型不受影响。</p></template>
  <template v-if="modal==='revoke'"><div class="confirm-title"><Icon name="KeyRound"/>{{tokenTarget}}</div><p>使用此 Token 的调用将无法通过认证。</p><p class="muted">撤销后无法恢复。</p></template>
  <template v-if="modal==='leave-confirm'"><p>启动页面有未保存的修改。</p><p class="muted">离开将放弃本次修改。</p></template>
  <p v-if="errors" class="error" role="alert">{{errors}}</p>
</div><footer><button @click="closeModal" :disabled="busy">{{modal==='leave-confirm'?'继续编辑':'取消'}}</button><button :class="modal==='delete'||modal==='revoke'?'danger-solid':'primary'" :disabled="!canSubmit" @click="submit">{{busy?'处理中…':modal==='create'?'创建用户':modal==='delete'?'删除用户':modal==='revoke'?'撤销 Token':modal==='leave-confirm'?'放弃修改并离开':'保存'}}</button></footer></dialog></div>
<aside v-if="review" class="review-tools"><strong>设置设计样稿</strong><select aria-label="设计场景" :value="scene.id" @change="changeScene"><option v-for="s in scenes" :value="s.id">{{s.name}}</option></select><button @click="setTheme(theme==='light'?'dark':'light')">{{theme==='light'?'暗色':'亮色'}}</button><button @click="review=false" aria-label="隐藏设计工具"><Icon name="X"/></button></aside>
</template>
